class Solution {
public:
    vector<int> maximumMEX(vector<int>& nums) {
        int n=nums.size();
        vector<int> freq(n+2,0);
        for(int x:nums) if(x<=n) ++freq[x];
        set<int> missing;
        for(int x=0;x<=n;++x) if(freq[x]==0) missing.insert(x);
        vector<int> ans;
        int i=0;
        while(i<n) {
            int mex=*missing.begin();
            ans.push_back(mex);
            if(mex==0) {
                int x=nums[i++];
                if(x<=n && --freq[x]==0) missing.insert(x);
            } else {
                vector<char> seen(mex,0);
                int remaining=mex;
                while(remaining) {
                    int x=nums[i++];
                    if(x<mex && !seen[x]) { seen[x]=1; --remaining; }
                    if(x<=n && --freq[x]==0) missing.insert(x);
                }
            }
        }
        return ans;
    }
};
